import { describe, it, expect, vi } from 'vitest';
import { CancelSubscriptionUseCase } from './CancelSubscriptionUseCase';
import { SubscriptionRepository } from '../domain/repositories/SubscriptionRepository';
import { SubscriptionId } from '../domain/value-objects/SubscriptionId';
import { SubscriptionStatus } from '../domain/enums/SubscriptionStatus';
import { Subscription } from '../domain/entities/Subscription';
import { DomainEventPublisher } from '../domain/events/DomainEventPublisher';
import { SubscriptionCancelledEvent } from '../domain/events/SubscriptionCancelledEvent';
import { Result } from '../domain/types/Result';

describe('CancelSubscriptionUseCase', () => {
  it('should cancel subscription and publish event when subscription exists and is active', async () => {
    // Arrange
    const mockSubscriptionId = new SubscriptionId('sub-123');
    const mockSubscription = new Subscription(
      mockSubscriptionId,
      'user-456',
      SubscriptionStatus.ACTIVE,
      new Date(),
      new Date()
    );

    const mockRepository = {
      findById: vi.fn(),
      save: vi.fn()
    } as unknown as SubscriptionRepository;

    const mockEventPublisher = {
      publish: vi.fn()
    } as unknown as DomainEventPublisher;

    const useCase = new CancelSubscriptionUseCase(mockRepository, mockEventPublisher);

    mockRepository.findById.mockResolvedValueOnce(Result.success(mockSubscription));
    mockRepository.save.mockResolvedValueOnce(Result.success(undefined));

    // Act
    const result = await useCase.execute(mockSubscriptionId);

    // Assert
    expect(result.isSuccess).toBe(true);
    expect(mockRepository.findById).toHaveBeenCalledWith(mockSubscriptionId);
    expect(mockRepository.save).toHaveBeenCalledWith(mockSubscription);
    expect(mockSubscription.status).toBe(SubscriptionStatus.CANCELLED);
    expect(mockEventPublisher.publish).toHaveBeenCalledWith(
      new SubscriptionCancelledEvent(mockSubscriptionId, 'user-456')
    );
  });

  it('should return error when subscription does not exist', async () => {
    // Arrange
    const mockSubscriptionId = new SubscriptionId('sub-nonexistent');

    const mockRepository = {
      findById: vi.fn(),
      save: vi.fn()
    } as unknown as SubscriptionRepository;

    const mockEventPublisher = {
      publish: vi.fn()
    } as unknown as DomainEventPublisher;

    const useCase = new CancelSubscriptionUseCase(mockRepository, mockEventPublisher);

    mockRepository.findById.mockResolvedValueOnce(Result.failure('Subscription not found'));

    // Act
    const result = await useCase.execute(mockSubscriptionId);

    // Assert
    expect(result.isSuccess).toBe(false);
    expect(result.error).toBe('Subscription not found');
    expect(mockRepository.save).not.toHaveBeenCalled();
    expect(mockEventPublisher.publish).not.toHaveBeenCalled();
  });

  it('should return error when subscription is already cancelled', async () => {
    // Arrange
    const mockSubscriptionId = new SubscriptionId('sub-123');
    const mockSubscription = new Subscription(
      mockSubscriptionId,
      'user-456',
      SubscriptionStatus.CANCELLED,
      new Date(),
      new Date()
    );

    const mockRepository = {
      findById: vi.fn(),
      save: vi.fn()
    } as unknown as SubscriptionRepository;

    const mockEventPublisher = {
      publish: vi.fn()
    } as unknown as DomainEventPublisher;

    const useCase = new CancelSubscriptionUseCase(mockRepository, mockEventPublisher);

    mockRepository.findById.mockResolvedValueOnce(Result.success(mockSubscription));

    // Act
    const result = await useCase.execute(mockSubscriptionId);

    // Assert
    expect(result.isSuccess).toBe(false);
    expect(result.error).toBe('Subscription is already cancelled');
    expect(mockRepository.save).not.toHaveBeenCalled();
    expect(mockEventPublisher.publish).not.toHaveBeenCalled();
  });

  it('should return error when subscription is expired', async () => {
    // Arrange
    const mockSubscriptionId = new SubscriptionId('sub-123');
    const mockSubscription = new Subscription(
      mockSubscriptionId,
      'user-456',
      SubscriptionStatus.EXPIRED,
      new Date(),
      new Date()
    );

    const mockRepository = {
      findById: vi.fn(),
      save: vi.fn()
    } as unknown as SubscriptionRepository;

    const mockEventPublisher = {
      publish: vi.fn()
    } as unknown as DomainEventPublisher;

    const useCase = new CancelSubscriptionUseCase(mockRepository, mockEventPublisher);

    mockRepository.findById.mockResolvedValueOnce(Result.success(mockSubscription));

    // Act
    const result = await useCase.execute(mockSubscriptionId);

    // Assert
    expect(result.isSuccess).toBe(false);
    expect(result.error).toBe('Cannot cancel expired subscription');
    expect(mockRepository.save).not.toHaveBeenCalled();
    expect(mockEventPublisher.publish).not.toHaveBeenCalled();
  });
});
