// In-memory test doubles (fakes)
class InMemoryOrderRepository implements IOrderRepository {
  public readonly savedOrders: Order[] = [];

  async save(order: Order): Promise<void> {
    this.savedOrders.push(order);
  }
}

class FakeNotificationPort implements INotificationPort {
  public readonly notificationsSent: { customerId: string; orderId: string }[] = [];

  async sendOrderCreated(customerId: string, orderId: string): Promise<void> {
    this.notificationsSent.push({ customerId, orderId });
  }
}

describe('CreateOrderUseCase (Unit Tests)', () => {
  let orderRepo: InMemoryOrderRepository;
  let notifier: FakeNotificationPort;
  let useCase: CreateOrderUseCase;

  beforeEach(() => {
    orderRepo = new InMemoryOrderRepository();
    notifier = new FakeNotificationPort();
    useCase = new CreateOrderUseCase(orderRepo, notifier);
  });

  it('should successfully create an order and notify customer when items are valid (AAA)', async () => {
    // 1. Arrange
    const dto = {
      customerId: 'cust-123',
      items: [
        { productId: 'prod-A', price: 10, quantity: 2 },
        { productId: 'prod-B', price: 5, quantity: 1 },
      ],
    };

    // 2. Act
    const result = await useCase.execute(dto);

    // 3. Assert
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.total).toBe(25); // (10*2) + (5*1)
      expect(orderRepo.savedOrders).toHaveLength(1);
      expect(orderRepo.savedOrders[0].id).toBe(result.orderId);
      expect(notifier.notificationsSent).toHaveLength(1);
      expect(notifier.notificationsSent[0].customerId).toBe('cust-123');
    }
  });

  it('should fail with an error when items list is empty (AAA)', async () => {
    // 1. Arrange
    const dto = {
      customerId: 'cust-123',
      items: [],
    };

    // 2. Act
    const result = await useCase.execute(dto);

    // 3. Assert
    expect(result.success).toBe(false);
    if (!result.success) {
      expect(result.error).toContain('Order must contain at least one item');
    }
    expect(orderRepo.savedOrders).toHaveLength(0);
    expect(notifier.notificationsSent).toHaveLength(0);
  });
});
