// Domain Layer - User Entity and Value Objects
export interface User {
  id: string;
  email: string;
  passwordHash: string;
}

export interface Email {
  to: string;
  subject: string;
  body: string;
}

// Domain Layer - Domain Errors
export type UserRegistrationError =
  | { type: 'InvalidEmail' }
  | { type: 'UserAlreadyExists' };

// Application Layer - Use Case
export interface RegisterUserUseCase {
  execute(email: string, password: string): Promise<Result<User, UserRegistrationError>>;
}

// Infrastructure Layer - Repository Interface
export interface IUserRepository {
  findByEmail(email: string): Promise<User | null>;
  save(user: User): Promise<User>;
}

// Infrastructure Layer - Email Service Interface
export interface IEmailService {
  sendWelcomeEmail(email: string): Promise<void>;
}

// Application Layer - Implementation
export class RegisterUserUseCaseImpl implements RegisterUserUseCase {
  constructor(
    private readonly userRepository: IUserRepository,
    private readonly emailService: IEmailService
  ) {}

  async execute(email: string, password: string): Promise<Result<User, UserRegistrationError>> {
    // Validate email format
    if (!email.includes('@')) {
      return Result.failure({ type: 'InvalidEmail' });
    }

    // Check if user already exists
    const existingUser = await this.userRepository.findByEmail(email);
    if (existingUser !== null) {
      return Result.failure({ type: 'UserAlreadyExists' });
    }

    // Create user (password hashing handled in repository or domain)
    const user: User = {
      id: crypto.randomUUID(),
      email,
      passwordHash: await this.hashPassword(password)
    };

    try {
      const savedUser = await this.userRepository.save(user);

      // Send welcome email
      await this.emailService.sendWelcomeEmail(email);

      return Result.success(savedUser);
    } catch (error) {
      // Handle repository or email service errors
      throw new Error('Failed to register user');
    }
  }

  private async hashPassword(password: string): Promise<string> {
    // This could be moved to a dedicated password service
    return bcrypt.hash(password, 10);
  }
}

// Infrastructure Layer - Express Route Handler
export const createRegisterUserHandler = (
  registerUserUseCase: RegisterUserUseCase
) => {
  return async (req: Request, res: Response): Promise<void> => {
    const { email, password } = req.body;

    const result = await registerUserUseCase.execute(email, password);

    if (result.isFailure()) {
      const error = result.error;
      switch (error.type) {
        case 'InvalidEmail':
          res.status(400).send('Invalid email');
          return;
        case 'UserAlreadyExists':
          res.status(409).send('User exists');
          return;
      }
    }

    const user = result.value;
    res.status(201).json({ id: user.id });
  };
};

// Express Route Setup
const registerUserUseCase = new RegisterUserUseCaseImpl(userRepository, emailService);
app.post('/users', createRegisterUserHandler(registerUserUseCase));
