  | { type: 'InvalidEmail' }
  | { type: 'UserAlreadyExists' };

// Domain Layer - Repository Interface
export interface IUserRepository {
  findByEmail(email: string): Promise<User | null>;
  save(user: User): Promise<User>;
}

// Domain Layer - Email Service Interface
export interface IEmailService {
  sendWelcomeEmail(to: string): Promise<void>;
}

// Application Layer - Use Case
export interface RegisterUserUseCase {
  execute(email: string, password: string): Promise<Result<User, UserError>>;
}

// Application Layer - Use Case Implementation
export class RegisterUser implements RegisterUserUseCase {
  constructor(
    private readonly userRepository: IUserRepository,
    private readonly emailService: IEmailService,
    private readonly passwordHasher: PasswordHasher
  ) {}

  async execute(email: string, password: string): Promise<Result<User, UserError>> {
    // Validate email
    if (!this.isValidEmail(email)) {
      return Result.failure<User, UserError>({ type: 'InvalidEmail' });
    }

    // Check if user already exists
    const existingUser = await this.userRepository.findByEmail(email);
    if (existingUser) {
      return Result.failure<User, UserError>({ type: 'UserAlreadyExists' });
    }

    // Hash password
    const passwordHash = await this.passwordHasher.hash(password);

    // Create user entity
    const user: User = {
      id: crypto.randomUUID(),
      email,
      passwordHash
    };

    // Save user
    const savedUser = await this.userRepository.save(user);

    // Send welcome email
    try {
      await this.emailService.sendWelcomeEmail(email);
    } catch (error) {
      // Log error but don't fail the operation
      console.error('Failed to send welcome email:', error);
    }

    return Result.success<User, UserError>(savedUser);
  }

  private isValidEmail(email: string): boolean {
    return email.includes('@');
  }
}

